@@ -0,0 +1,87 @@
+export function safeConfigMerge(base, overlay) {
+  const dangerousKeys = new Set(['__proto__', 'prototype', 'constructor']);
+
+  function isAllowedValue(val) {
+    if (val === null || typeof val === 'boolean' || typeof val === 'string') return true;
+    if (typeof val === 'number') return Number.isFinite(val);
+    if (Array.isArray(val)) return val.every(isAllowedValue);
+    if (typeof val === 'object' && val !== null) {
+      return Object.getPrototypeOf(val) === Object.prototype;
+    }
+    return false;
+  }
+
+  function isPlainObject(val) {
+    return typeof val === 'object' && val !== null && Object.getPrototypeOf(val) === Object.prototype;
+  }
+
+  function deepFreeze(obj) {
+    if (!isPlainObject(obj)) return obj;
+    Object.freeze(obj);
+    for (const key of Object.keys(obj)) {
+      const value = obj[key];
+      if (Array.isArray(value)) {
+        obj[key] = value.slice().map(deepFreeze);
+        Object.freeze(obj[key]);
+      } else if (isPlainObject(value)) {
+        obj[key] = deepFreeze(value);
+      }
+    }
+    return obj;
+  }
+
+  function merge(base, overlay) {
+    const result = {};
+
+    // Collect all keys from both
+    const allKeys = new Set([...Object.keys(base), ...Object.keys(overlay)]);
+
+    for (const key of allKeys) {
+      if (dangerousKeys.has(key)) {
+        throw new RangeError(`Dangerous key rejected: ${key}`);
+      }
+
+      const baseVal = base[key];
+      const overlayVal = overlay[key];
+
+      // Check for unsupported values in overlay first
+      if (!isAllowedValue(overlayVal)) {
+        throw new TypeError(`Unsupported value in overlay at key: ${key}`);
+      }
+
+      // Check for unsupported values in base (only if both exist and are objects)
+      if (baseVal !== undefined && !isAllowedValue(baseVal)) {
+        throw new TypeError(`Unsupported value in base at key: ${key}`);
+      }
+
+      if (isPlainObject(baseVal) && isPlainObject(overlayVal)) {
+        // Recursively merge plain objects
+        result[key] = merge(baseVal, overlayVal);
+      } else {
+        // Arrays and scalars replace wholesale
+        if (!isAllowedValue(overlayVal)) {
+          throw new TypeError(`Unsupported value in overlay at key: ${key}`);
+        }
+        result[key] = Array.isArray(overlayVal) ? overlayVal.slice().map(deepFreeze) : overlayVal;
+      }
+    }
+
+    // Sort keys lexicographically
+    const sortedKeys = Object.keys(result).sort();
+    const sortedResult = {};
+    for (const key of sortedKeys) {
+      sortedResult[key] = result[key];
+    }
+
+    return deepFreeze(sortedResult);
+  }
+
+  if (!isAllowedValue(base)) {
+    throw new TypeError('base must be a plain object or null');
+  }
+  if (!isAllowedValue(overlay)) {
+    throw new TypeError('overlay must be a plain object or null');
+  }
+
+  return merge(base, overlay);
+}

